export type Language = 'en' | 'zh' | 'zh-TW';

let currentLang: Language = 'zh';

export function setLanguage(lang: Language): void {
	currentLang = lang;
}

export function getLanguage(): Language {
	return currentLang;
}

/** Verification surface: the raw key set of one language's dictionary (the
 *  verify-i18n script asserts key parity and placeholder integrity). */
export function translationKeys(lang: Language): string[] {
	return Object.keys(translations[lang]);
}

/** Verification surface: one raw entry (undefined when the key is absent). */
export function translationEntry(lang: Language, key: string): string | undefined {
	return translations[lang][key];
}

/** BCP-47 locale for date/number formatting: the UI language mapped to its
 *  locale. zh-TW keeps its own; zh renders zh-CN dates (previous call sites
 *  hardcoded this pair). */
export function getLocale(): string {
	if (currentLang === 'zh-TW') return 'zh-TW';
	if (currentLang === 'zh') return 'zh-CN';
	return 'en';
}

